        "\u05C0\u0599\u33A9\u05B7\u05B7\u05B7\u05B7\u05B7\u05B7\u05B7\u05B7\u05A1\u3106\u24DF\u1E57\u05E4\u043F\uFB44\uFB44\u333B\uFB43\u067E\u057A\u05E4\uFB57\uFB58\u307A\uFB59\u30DA\u04A7\uFB4E%\u066A\uFF05\uFE6A.\u0589\u00B7\uFF61\uF6E7\uFF0E\uFE52\uF6E8\u0342\u22A5\u2030\u20A7\u338A\u09AB\u092B\u0AAB\u0A2B\u03C6\u03D5\u327A\u321A\u326C\u314D\u320C\u0278\u0E3A\u03D5\u01A5\u0E1E\u0E1C\u0E20\u03C0\u3273\u3213\u3176\u3265\u3172\u3142\u3205\u3174\u3144\u3175\u3177\u3173\u3074" +
